<#
.SYNOPSIS
  Inicializa un proyecto con la configuración base de Claude Code y verifica el resultado.

.DESCRIPTION
  Script autocontenido: lleva dentro (comprimida en base64) toda la configuración
  base y la escribe en el proyecto destino, se asegura de que el plugin
  mattpocock-skills esté instalado a nivel usuario y termina con un checklist en
  consola de todo lo configurado.
  Nunca pisa archivos existentes salvo que se pase -Force.
  El script termina con código 1 si alguna verificación falla.

.PARAMETER Target
  Carpeta del proyecto. Por defecto, la carpeta actual.

.PARAMETER Force
  Sobrescribe los archivos que ya existen en el destino.

.PARAMETER SkipPlugin
  No comprueba ni instala el plugin mattpocock-skills.

.PARAMETER CheckOnly
  Solo verifica el destino, sin escribir nada ni instalar el plugin.

.EXAMPLE
  .\init.ps1 -Target C:\Users\Usuario\Documents\GitHub\mi-proyecto

.EXAMPLE
  .\init.ps1 -Target C:\ruta\al\proyecto -CheckOnly
#>
[CmdletBinding()]
param(
  [string]$Target = (Get-Location).Path,
  [switch]$Force,
  [switch]$SkipPlugin,
  [switch]$CheckOnly
)

$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [Text.Encoding]::UTF8
Add-Type -AssemblyName System.IO.Compression

$plugin = 'mattpocock-skills@claude-plugins-official'

# --- Progreso y logs ---------------------------------------------------

$script:barOpen = $false

function Write-Log([string]$msg, [string]$level = 'info') {
  if ($script:barOpen) { Write-Host ''; $script:barOpen = $false }
  $color = switch ($level) { 'ok' { 'Green' } 'warn' { 'Yellow' } 'err' { 'Red' } default { 'Gray' } }
  Write-Host ('[{0}] {1}' -f (Get-Date -Format 'HH:mm:ss'), $msg) -ForegroundColor $color
}

# Barra de progreso. En consola interactiva se redibuja en la misma línea;
# si la salida está redirigida imprime una línea cada 10 pasos.
function Write-Bar([string]$label, [int]$current, [int]$total) {
  if ($total -le 0) { return }
  $width = 30
  $filled = [int][math]::Floor($width * $current / $total)
  $bar = ([string][char]0x2588) * $filled + ([string][char]0x2591) * ($width - $filled)
  $pct = [int][math]::Floor(100 * $current / $total)
  $label = $label.PadRight(48).Substring(0, 48)
  $line = '  [{0}] {1,3}% {2} ({3}/{4})' -f $bar, $pct, $label, $current, $total
  if ([Console]::IsOutputRedirected) {
    if ($current -eq $total -or $current % 10 -eq 0) { Write-Host $line -ForegroundColor Cyan }
    return
  }
  Write-Host ("`r" + $line) -NoNewline -ForegroundColor Cyan
  $script:barOpen = $true
  if ($current -eq $total) { Write-Host ''; $script:barOpen = $false }
}

Write-Log "Inicio: init.ps1 (Target=$Target, CheckOnly=$($CheckOnly.IsPresent), Force=$($Force.IsPresent))"

# ZIP en base64 con todos los archivos de la plantilla (rutas relativas con /).
$payload = ''

Write-Log '[1/5] Leyendo plantilla incrustada'
$zip = New-Object IO.Compression.ZipArchive((New-Object IO.MemoryStream(, [Convert]::FromBase64String($payload))), [IO.Compression.ZipArchiveMode]::Read)
$entries = @($zip.Entries | Where-Object { $_.Name })
Write-Log "Plantilla leída: $($entries.Count) archivos" 'ok'

if (-not (Test-Path $Target)) {
  if ($CheckOnly) { throw "No existe $Target" }
  New-Item -ItemType Directory -Path $Target | Out-Null
}
$Target = (Resolve-Path $Target).Path


# --- Escritura ---------------------------------------------------------

$copied = 0
$skipped = @()

if (-not $CheckOnly) {
  Write-Log "[2/5] Escribiendo $($entries.Count) archivos en $Target"
  $idx = 0
  foreach ($entry in $entries) {
    $idx++
    Write-Bar $entry.FullName $idx $entries.Count
    $relative = $entry.FullName.Replace('/', '\')
    $dest = Join-Path $Target $relative

    if ((Test-Path $dest) -and -not $Force) {
      $skipped += $relative
      Write-Log "Omitido (ya existe): $relative" 'warn'
      continue
    }

    New-Item -ItemType Directory -Path (Split-Path $dest) -Force | Out-Null
    $in = $entry.Open()
    $out = [IO.File]::Create($dest)
    try { $in.CopyTo($out) } finally { $out.Dispose(); $in.Dispose() }
    $copied++
  }

  Write-Log "Escritos: $copied archivos en $Target" 'ok'
  if ($skipped.Count -gt 0) {
    Write-Log "Omitidos (ya existían, usa -Force para sobrescribir): $($skipped.Count)" 'warn'
  }
}

# --- Plugin ------------------------------------------------------------

$installedFile = Join-Path $env:USERPROFILE '.claude\plugins\installed_plugins.json'

function Test-PluginInstalled {
  (Test-Path $installedFile) -and ((Get-Content $installedFile -Raw) -match [regex]::Escape($plugin))
}

Write-Log "[3/5] Comprobando plugin $plugin"
if (Test-PluginInstalled) { Write-Log 'Plugin ya instalado' 'ok' }
if (-not $CheckOnly -and -not $SkipPlugin -and -not (Test-PluginInstalled)) {
  if (Get-Command claude -ErrorAction SilentlyContinue) {
    Write-Log "Instalando $plugin ..."
    claude plugin install $plugin --scope user
  } else {
    Write-Warning "No se encontró el comando claude. Instala el plugin a mano: claude plugin install $plugin"
  }
}

# --- Checklist ---------------------------------------------------------

$ok = [string][char]0x2713
$bad = [string][char]0x2717
$warn = '!'
$script:fails = 0
$script:warns = 0
$script:total = 0

function Write-Section([string]$title) {
  Write-Host ''
  Write-Host $title -ForegroundColor Cyan
}

# Estado: pass | fail | warn
function Write-Check([string]$state, [string]$label, [string]$detail = '') {
  $script:total++
  switch ($state) {
    'pass' { $mark = $ok;   $color = 'Green' }
    'warn' { $mark = $warn; $color = 'Yellow'; $script:warns++ }
    default { $mark = $bad; $color = 'Red';    $script:fails++ }
  }
  $line = "  $mark $label"
  if ($detail) { $line += "  ($detail)" }
  Write-Host $line -ForegroundColor $color
}

function Test-Item([string]$relative, [string]$label, [switch]$Optional) {
  $path = Join-Path $Target $relative
  if (Test-Path $path) {
    Write-Check pass $label
  } elseif ($Optional) {
    Write-Check warn $label 'falta'
  } else {
    Write-Check fail $label 'falta'
  }
}

function Get-Sha256([IO.Stream]$stream) {
  $sha = [Security.Cryptography.SHA256]::Create()
  try { [BitConverter]::ToString($sha.ComputeHash($stream)) } finally { $sha.Dispose(); $stream.Dispose() }
}

# Compara un archivo con su copia dentro del script para detectar cambios locales.
function Get-Drift([string]$relative) {
  $dst = Join-Path $Target $relative
  if (-not (Test-Path $dst)) { return 'missing' }
  $entry = $zip.GetEntry($relative.Replace('\', '/'))
  if (-not $entry) { return 'same' }
  $a = Get-Sha256 $entry.Open()
  $b = Get-Sha256 ([IO.File]::OpenRead($dst))
  if ($a -eq $b) { 'same' } else { 'changed' }
}

Write-Host ''
Write-Log '[4/5] Verificando (checks en vivo)'
Write-Host "Verificación de $Target" -ForegroundColor White

# Entorno
Write-Section 'Entorno'
if (Get-Command claude -ErrorAction SilentlyContinue) { Write-Check pass 'CLI claude disponible' } else { Write-Check fail 'CLI claude disponible' 'no está en el PATH' }
if (Test-Path (Join-Path $Target '.git')) { Write-Check pass 'Repositorio git' } else { Write-Check warn 'Repositorio git' 'ejecuta git init' }

# Contenido completo
Write-Section 'Contenido de la plantilla'
$missing = @($entries | Where-Object { -not (Test-Path (Join-Path $Target $_.FullName.Replace('/', '\'))) })
if ($missing.Count -eq 0) {
  Write-Check pass 'Todos los archivos presentes' "$($entries.Count) archivos"
} else {
  Write-Check fail 'Todos los archivos presentes' "faltan $($missing.Count) de $($entries.Count)"
  $missing | Select-Object -First 10 | ForEach-Object { Write-Host "      - $($_.FullName)" -ForegroundColor Red }
  if ($missing.Count -gt 10) { Write-Host "      ... y $($missing.Count - 10) más" -ForegroundColor Red }
}

# settings.json
Write-Section 'Permisos (.claude/settings.json)'
$settingsPath = Join-Path $Target '.claude\settings.json'
if (Test-Path $settingsPath) {
  try {
    $s = Get-Content $settingsPath -Raw | ConvertFrom-Json
    Write-Check pass 'JSON válido'

    if ($s.permissions.defaultMode -eq 'plan') { Write-Check pass 'defaultMode = plan' }
    else { Write-Check warn 'defaultMode = plan' "actual: $($s.permissions.defaultMode)" }

    $allow = @($s.permissions.allow)
    foreach ($rule in 'Bash(git status)', 'Bash(git diff *)', 'Bash(git log *)') {
      if ($allow -contains $rule) { Write-Check pass "allow $rule" } else { Write-Check warn "allow $rule" 'falta' }
    }

    $deny = @($s.permissions.deny)
    foreach ($rule in 'Read(./.env)', 'Read(./.env.*)', 'Read(**/.env)', 'Read(**/.env.*)') {
      if ($deny -contains $rule) { Write-Check pass "deny $rule" } else { Write-Check fail "deny $rule" 'falta, los secretos quedan expuestos' }
    }
  } catch {
    Write-Check fail 'JSON válido' $_.Exception.Message
  }
} else {
  Write-Check fail 'settings.json' 'falta'
}
Test-Item '.claude\settings.local.json' 'settings.local.json (hooks de impeccable)' -Optional

# CLAUDE.md
Write-Section 'Guía del proyecto (CLAUDE.md)'
$claudeMd = Join-Path $Target 'CLAUDE.md'
if (Test-Path $claudeMd) {
  Write-Check pass 'CLAUDE.md existe'
  $text = Get-Content $claudeMd -Raw -Encoding UTF8
  if ($text -match 'skill caveman') { Write-Check pass 'Activa caveman' } else { Write-Check warn 'Activa caveman' 'sin la línea de activación' }
  if ($text -match 'Responde en español') { Write-Check pass 'Responde en español' } else { Write-Check warn 'Responde en español' 'sin la instrucción' }
  $pending = ([regex]::Matches($text, '<!--')).Count
  # Una sección sin contenido (título seguido de otro título o del final) cuenta como pendiente.
  $emptySections = ([regex]::Matches($text, '(?m)^##+ .+\r?\n(\s*\r?\n)*(?=#{1,2} |\z)')).Count
  if ($pending -eq 0 -and $emptySections -eq 0) { Write-Check pass 'Secciones rellenadas' }
  else { Write-Check warn 'Secciones rellenadas' "$pending comentarios <!-- --> y $emptySections secciones vacías por completar" }
} else {
  Write-Check fail 'CLAUDE.md' 'falta'
}

# Agentes
Write-Section 'Agentes (.claude/agents)'
foreach ($a in 'impeccable-asset-producer', 'impeccable-documenter', 'impeccable-finish-reviewer', 'impeccable-manual-edit-applier') {
  Test-Item ".claude\agents\$a.md" $a
}

# Skills
Write-Section 'Skills (.claude/skills)'
foreach ($sk in 'ds-poderosa', 'impeccable') {
  Test-Item ".claude\skills\$sk\SKILL.md" "$sk/SKILL.md"
}
foreach ($f in 'brand.md', 'meanings.md', 'tokens.md', 'tokens.css') {
  Test-Item ".claude\skills\ds-poderosa\core\$f" "ds-poderosa/core/$f"
}
Test-Item '.claude\skills\impeccable\scripts\bin\windows-x64\impeccable.exe' 'impeccable/scripts: binario windows'
$refCount = 0
$refDir = Join-Path $Target '.claude\skills\impeccable\reference'
if (Test-Path $refDir) { $refCount = (Get-ChildItem $refDir -Recurse -File).Count }
if ($refCount -gt 0) { Write-Check pass 'impeccable/reference' "$refCount archivos" } else { Write-Check fail 'impeccable/reference' 'vacía' }

# Docs de los skills de Matt
Write-Section 'Docs para skills de Matt (docs/agents)'
foreach ($f in 'issue-tracker.md', 'triage-labels.md', 'domain.md') {
  Test-Item "docs\agents\$f" $f
}

# Estructura de docs y proyecto
Write-Section 'Estructura (docs/ y app/)'
foreach ($p in 'docs\README.md', 'docs\inputs\README.md', 'docs\plan\README.md', 'docs\plan\checklist.md', 'docs\specs\README.md', 'app\README.md') {
  Test-Item $p $p
}
# Plugin
Write-Section 'Plugin de usuario'
if (Test-PluginInstalled) { Write-Check pass $plugin }
elseif ($SkipPlugin) { Write-Check warn $plugin 'omitido (-SkipPlugin)' }
else { Write-Check fail $plugin 'no instalado' }

# .gitignore
Write-Section 'Git (.gitignore)'
$gi = Join-Path $Target '.gitignore'
if (Test-Path $gi) {
  $giText = Get-Content $gi -Raw
  foreach ($entry in '.claude/settings.local.json', 'CLAUDE.local.md', '.claude/worktrees/') {
    if ($giText -match [regex]::Escape($entry)) { Write-Check pass "ignora $entry" } else { Write-Check warn "ignora $entry" 'falta' }
  }
} else {
  Write-Check warn '.gitignore' 'falta'
}

# Diferencias con la plantilla
Write-Section 'Cambios locales frente a la plantilla'
$drift = @()
Write-Log '[5/5] Comparando archivos con la plantilla'
$n = 0
foreach ($e in $entries) {
  $n++
  Write-Bar $e.FullName $n $entries.Count
  if ((Get-Drift $e.FullName.Replace('/', '\')) -eq 'changed') { $drift += $e.FullName.Replace('/', '\') }
}
if ($drift.Count -eq 0) {
  Write-Check pass 'Archivos idénticos a la plantilla'
} else {
  foreach ($f in $drift | Select-Object -First 10) { Write-Check warn $f 'distinto de la plantilla' }
  if ($drift.Count -gt 10) { Write-Check warn "y $($drift.Count - 10) archivos más" 'distintos de la plantilla' }
}

# Resumen
$passed = $script:total - $script:fails - $script:warns
Write-Host ''
$summaryColor = 'Green'
if ($script:fails -gt 0) { $summaryColor = 'Red' } elseif ($script:warns -gt 0) { $summaryColor = 'Yellow' }
Write-Log 'Verificación terminada' 'ok'
Write-Host ("Resultado: {0} correctos, {1} avisos, {2} errores de {3}" -f $passed, $script:warns, $script:fails, $script:total) -ForegroundColor $summaryColor

$zip.Dispose()

if ($script:fails -gt 0) {
  Write-Host 'Corrige los errores y vuelve a ejecutar con -CheckOnly.'
  exit 1
}
if ($script:warns -gt 0) {
  Write-Host 'Siguiente paso: completar CLAUDE.md y revisar los avisos.'
} else {
  Write-Host 'Todo en orden.'
}
